  q(CONS,'Which trend gives patients more control over choosing providers and comparing prices?','Healthcare consumerism',['Vertical integration','Physician shortages','Paper medical records'],'A','Online reviews, price tools and HSAs support consumer choice.',BUCH),
  q(CONS,'What is a whistleblower?','An employee who reports wrongdoing',['A manager who hires new staff','A patient who files a claim','A vendor who sells supplies'],'B','Federal laws such as the False Claims Act protect whistleblowers from retaliation by employers.',BUCH)
